const D = { energy:.6, scale:1, speed:1, hue:30, x:.5, y:.5, style:'planck', seed:0, alpha:100, warp:.5 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const style = P.style, sd = (P.seed | 0);

// ---- adaptive field buffer ----
const BW = Math.max(360, Math.min(560, Math.round(width / 3.0)));
const BH = Math.max(120, Math.round(BW * height / width));
const LC = Math.max(3, 9 / (0.5 + P.scale));            // lattice cells across width (feature size)
const buildKey = BW + 'x' + BH + '|' + sd + '|' + LC.toFixed(2);
if (!S.gfx || S.bw !== BW || S.bh !== BH) { S.gfx = createGraphics(BW, BH); S.gfx.pixelDensity(1); S.bw = BW; S.bh = BH; S.buildKey = null; }
const g = S.gfx;

// ---- build 3 static gaussian-random temperature fields once per (seed,scale,size) ----
if (S.buildKey !== buildKey) {
  S.buildKey = buildKey;
  const hash = (ix, iy, so) => { const s = Math.sin(ix * 127.1 + iy * 311.7 + so * 74.7) * 43758.5453; return s - Math.floor(s); };
  const smooth = t => t * t * (3 - 2 * t);
  const lat = (x, y, so) => { const x0 = Math.floor(x), y0 = Math.floor(y), fx = smooth(x - x0), fy = smooth(y - y0);
    const a = hash(x0, y0, so), b = hash(x0 + 1, y0, so), c = hash(x0, y0 + 1, so), d = hash(x0 + 1, y0 + 1, so);
    return (a * (1 - fx) + b * fx) * (1 - fy) + (c * (1 - fx) + d * fx) * fy; };
  S.fld = [];
  for (let k = 0; k < 3; k++) {
    const F = new Float32Array(BW * BH);
    const so = sd * 3 + k * 97;
    let mn = 1e9, mx = -1e9;
    for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
      const fx = i / BW, fy = j / BW; // keep isotropic cells
      let v = 0, amp = 1, f = LC, norm = 0;
      for (let o = 0; o < 4; o++) { v += amp * lat(fx * f + o * 13.7, fy * f + o * 9.1, so + o * 31); norm += amp; amp *= 0.52; f *= 2.05; }
      v /= norm; F[j * BW + i] = v;
      if (v < mn) mn = v; if (v > mx) mx = v;
    }
    const inv = 1 / (mx - mn + 1e-6);
    for (let i = 0; i < F.length; i++) F[i] = (F[i] - mn) * inv - 0.5; // centered ~[-0.5,0.5]
    S.fld.push(F);
  }
}
const F0 = S.fld[0], F1 = S.fld[1], F2 = S.fld[2];

// ---- per-frame slow boil: incommensurate weights + tiny domain warp (NON-STROBE) ----
const T = K.t * (0.5 + P.speed * 0.6);
let wa = 0.5 + 0.5 * Math.sin(T * 0.041), wb = 0.5 + 0.5 * Math.sin(T * 0.057 + 2.1), wc = 0.5 + 0.5 * Math.sin(T * 0.069 + 4.0);
const ws = 1 / (wa + wb + wc + 1e-6); wa *= ws; wb *= ws; wc *= ws;
const warpAmp = (1.5 + P.warp * 6) ;
const ox0 = warpAmp * Math.sin(T * 0.033), oy0 = warpAmp * Math.cos(T * 0.028);
const ox1 = warpAmp * Math.sin(T * 0.023 + 1.7), oy1 = warpAmp * Math.cos(T * 0.037 + 0.4);
const ox2 = warpAmp * Math.sin(T * 0.045 + 3.1), oy2 = warpAmp * Math.cos(T * 0.019 + 2.2);
const contrast = 1.4 + P.energy * 1.8;
const gain = 0.9 + K.swell * 0.08 + A.rms * 0.15;

// bilinear sampler over a field
function samp(F, x, y) {
  if (x < 0) x = 0; else if (x > BW - 1.001) x = BW - 1.001;
  if (y < 0) y = 0; else if (y > BH - 1.001) y = BH - 1.001;
  const xi = x | 0, yi = y | 0, fx = x - xi, fy = y - yi, o = yi * BW + xi;
  return (F[o] * (1 - fx) + F[o + 1] * fx) * (1 - fy) + (F[o + BW] * (1 - fx) + F[o + BW + 1] * fx) * fy;
}

g.loadPixels(); const pix = g.pixels;
// hue tints the deep-space ground outside the oval (subtle)
const hrad = P.hue * Math.PI / 180;
const gr0 = 4 + 7 * (0.5 + 0.5 * Math.cos(hrad));
const gg0 = 5 + 7 * (0.5 + 0.5 * Math.cos(hrad - 2.094));
const gb0 = 10 + 7 * (0.5 + 0.5 * Math.cos(hrad - 4.188));
for (let j = 0; j < BH; j++) {
  const ny = (j / BH - 0.5) * 2;            // -1..1
  for (let i = 0; i < BW; i++) {
    const nx = (i / BW - 0.5) * 2;
    const o = 4 * (j * BW + i);
    // Mollweide-ish oval mask (full-sky ellipse)
    const enx = nx / 0.95, eny = ny / 0.93;
    const ee = enx * enx + eny * eny;
    if (ee > 1.0) {
      // outside sky: dark deep ground (never pure black), hue-tinted
      pix[o] = gr0; pix[o + 1] = gg0; pix[o + 2] = gb0; pix[o + 3] = 255; continue;
    }
    let v = samp(F0, i + ox0, j + oy0) * wa + samp(F1, i + ox1, j + oy1) * wb + samp(F2, i + ox2, j + oy2) * wc;
    v = Math.max(-1, Math.min(1, v * contrast * gain));   // temperature -1..1
    const t = (v + 1) * 0.5;                               // 0 cold ..1 hot
    let r, gg, b;
    if (style === 'wmap') {                                // cold blue -> white -> hot red
      if (t < 0.5) { const s = t * 2; r = 40 + s * 200; gg = 40 + s * 200; b = 200 + s * 55; }
      else { const s = (t - 0.5) * 2; r = 240; gg = 240 - s * 190; b = 255 - s * 205; }
    } else if (style === 'thermal') {                      // black-body dark-red -> orange -> white
      r = Math.min(255, t * 340); gg = Math.min(255, Math.max(0, (t - 0.28) * 300)); b = Math.min(255, Math.max(0, (t - 0.62) * 380));
      r += 18; gg += 6; b += 10;
    } else if (style === 'contour') {                      // iso-temperature bands (schematic mono)
      const band = 0.5 + 0.5 * Math.cos(v * 22.0);
      const line = Math.pow(band, 6);
      const m = 0.16 + 0.5 * (t) + line * 0.5;
      r = m * 120; gg = m * 210; b = m * 255;
    } else {                                                // planck: blue-cyan-green-yellow-red
      const x5 = t * 4;
      if (x5 < 1) { const s = x5; r = 8 + s * 20; gg = 20 + s * 120; b = 120 + s * 135; }
      else if (x5 < 2) { const s = x5 - 1; r = 28 + s * 30; gg = 140 + s * 100; b = 255 - s * 175; }
      else if (x5 < 3) { const s = x5 - 2; r = 58 + s * 197; gg = 240 - s * 20; b = 80 - s * 60; }
      else { const s = x5 - 3; r = 255; gg = 220 - s * 200; b = 20 + s * 10; }
    }
    pix[o] = r > 255 ? 255 : (r < 0 ? 0 : r); pix[o + 1] = gg > 255 ? 255 : (gg < 0 ? 0 : gg); pix[o + 2] = b > 255 ? 255 : (b < 0 ? 0 : b); pix[o + 3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
noTint();
pop();

// faint graticule (meridians / parallels) over the oval — survey-plate look
if (style !== 'contour') {
  push();
  const cx = width * 0.5, cy = height * 0.5;
  const RX = width * 0.47, RY = height * 0.47;
  stroke(0, 0, 100, 7 * (P.alpha / 100)); noFill(); strokeWeight(Math.max(1, u * 0.0012));
  for (let m = -2; m <= 2; m++) {                          // meridians (vertical ellipse arcs)
    beginShape();
    for (let a = -90; a <= 90; a += 6) {
      const la = a * Math.PI / 180; const k = m / 3;
      const xx = cx + RX * k * Math.cos(la); const yy = cy + RY * Math.sin(la);
      vertex(xx, yy);
    }
    endShape();
  }
  for (let p2 = -2; p2 <= 2; p2++) {                        // parallels (horizontal chords)
    const yy = cy + RY * (p2 / 3) * 0.95;
    const half = RX * Math.sqrt(Math.max(0, 1 - (p2 / 3) * (p2 / 3)));
    line(cx - half, yy, cx + half, yy);
  }
  pop();
}
